ui.script:
// Screen for the arpeggiator: the step grid Custom plays, with a preset pictured on the same grid.
// Columns are steps, rows are slots of the held chord — slot 1, the lowest note, at the bottom —
// stacking up through the octaves. Under each step, its velocity bar, then its gate bar.
// A preset depends on the chord, so it is pictured for a 4-note one. Editing a preset (a cell or a bar)
// turns it into Custom, starting from what was shown (engine docs/arpeggiator.md).

const MAX = 16;
const CHORD = 4;
const NAMES = ["UP", "DOWN", "UP-DOWN", "RANDOM", "CUSTOM"];
const CUSTOM = 4;
const HEAD = 11;
const STRIP = 7;
// One bar row's height, and the gap above it.
const BAR = 16;
const GAP = 3;
// What an untouched step carries, and the span a gate may take — the plugin's own numbers.
const VEL_DEFAULT = 1;
const GATE_DEFAULT = 0.5;
const GATE_MIN = 0.05;
const GATE_MAX = 0.95;
const FONT = "8px ui-monospace, monospace";

function clamp(v, lo, hi) {
  return Math.max(lo, Math.min(hi, Number.isFinite(v) ? v : lo));
}

// The default the engine gives an untouched step: `up` over eight slots.
const stepDefault = (i) => (i % 8) + 1;

function octavesOf(p) {
  return clamp(Math.round(p.Octaves ?? 1), 1, 4);
}

// Enough rows for the chord across its octaves, never fewer than eight so a drawing has room.
function rowsOf(p) {
  return Math.min(MAX, Math.max(8, CHORD * octavesOf(p)));
}

// The steps a preset walks for a CHORD-note chord, as the engine's noteFor walks them.
function presetSteps(dir, oct) {
  const count = CHORD * oct;
  const out = [];
  if (dir === 1) for (let i = 0; i < count; i++) out.push(count - i);
  else if (dir === 2) {
    const period = count > 1 ? 2 * count - 2 : 1;
    for (let j = 0; j < period; j++) out.push((j < count ? j : period - j) + 1);
  } else if (dir === 3) {
    // The engine's xorshift and seed, so the picture is one random walk it could play.
    let s = 0x9e3779b9 >>> 0;
    for (let i = 0; i < count; i++) {
      s = (s ^ (s << 13)) >>> 0;
      s = (s ^ (s >>> 17)) >>> 0;
      s = (s ^ (s << 5)) >>> 0;
      out.push((s % count) + 1);
    }
  } else for (let i = 0; i < count; i++) out.push(i + 1);
  return out.slice(0, MAX);
}

// What the grid shows: the drawn steps under Custom, else the preset's walk at the default levels.
function patternOf(p) {
  const dir = Math.round(p.Direction ?? 0);
  if (dir === CUSTOM) {
    const steps = [];
    const vel = [];
    const gate = [];
    for (let i = 0; i < MAX; i++) {
      steps.push(Math.round(p[`Step ${i + 1}`] ?? stepDefault(i)));
      vel.push(clamp(p[`Velocity ${i + 1}`] ?? VEL_DEFAULT, 0, 1));
      gate.push(clamp(p[`Gate ${i + 1}`] ?? GATE_DEFAULT, GATE_MIN, GATE_MAX));
    }
    return { dir, steps, vel, gate, length: clamp(Math.round(p.Steps ?? 8), 1, MAX) };
  }
  const walk = presetSteps(dir, octavesOf(p));
  const steps = [];
  for (let i = 0; i < MAX; i++) steps.push(walk[i] ?? 0);
  return {
    dir,
    steps,
    vel: Array(MAX).fill(VEL_DEFAULT),
    gate: Array(MAX).fill(GATE_DEFAULT),
    length: walk.length,
  };
}

// Where everything sits: a title line, the grid, the length strip, then the velocity and gate bars.
function layout(W, H, rows) {
  const x0 = 3;
  const y0 = HEAD;
  const cw = (W - 6) / MAX;
  const rh = (H - HEAD - STRIP - 2 * (BAR + GAP) - 3) / rows;
  const stripY = y0 + rows * rh + 2;
  const velY = stripY + STRIP + GAP;
  return { x0, y0, cw, rh, stripY, velY, gateY: velY + BAR + GAP };
}

// A bar's 0..1 fill for a value, and the value under a pointer height — the gate spans its own range.
const gateFill = (g) => (g - GATE_MIN) / (GATE_MAX - GATE_MIN);
const barValue = (top, y) => clamp(1 - (y - top) / BAR, 0, 1);

function drawBar(ctx, x, w, top, fill, lit, color) {
  ctx.strokeStyle = color.dim;
  ctx.strokeRect(Math.round(x) + 0.5, Math.round(top) + 0.5, Math.max(1, w - 1), BAR - 1);
  const h = Math.round((BAR - 2) * clamp(fill, 0, 1));
  if (h <= 0) return;
  ctx.fillStyle = lit;
  ctx.fillRect(Math.round(x) + 1, Math.round(top) + BAR - 1 - h, Math.max(1, w - 2), h);
}

function draw(lcd) {
  const { ctx, width: W, height: H, params: p, color } = lcd;
  if (W < 60 || H < 40) return;
  const rows = rowsOf(p);
  const g = layout(W, H, rows);
  const pat = patternOf(p);

  ctx.font = FONT;
  ctx.textBaseline = "top";
  ctx.fillStyle = color.ink;
  ctx.textAlign = "left";
  ctx.fillText(NAMES[pat.dir] ?? "UP", 3, 1);
  ctx.fillStyle = color.dim;
  ctx.textAlign = "right";
  // While a bar is dragged, the right of the title says what it is set to.
  const e = lcd.state.edit;
  const shown =
    e && (e.mode === "velocity" || e.mode === "gate") && e.col != null
      ? `${e.col + 1}: ${e.mode === "velocity" ? "VEL" : "GATE"} ${Math.round((e.mode === "velocity" ? e.vel : e.gate)[e.col] * 100)}%`
      : pat.dir === CUSTOM
        ? `${pat.length} STEPS`
        : `AS FOR ${CHORD} NOTES`;
  ctx.fillText(shown, W - 3, 1);

  for (let c = 0; c < MAX; c++) {
    const x = g.x0 + c * g.cw;
    const live = c < pat.length;
    // The cell outlines: faint past the pattern's end, a bar line every four steps.
    ctx.strokeStyle = live ? color.dim : "rgba(184,240,160,0.08)";
    ctx.lineWidth = 1;
    for (let r = 0; r < rows; r++)
      ctx.strokeRect(Math.round(x) + 0.5, Math.round(g.y0 + r * g.rh) + 0.5, Math.max(1, g.cw - 1), Math.max(1, g.rh - 1));
    if (c % 4 === 0) {
      ctx.fillStyle = color.dim;
      ctx.fillRect(Math.round(x), g.y0, 1, rows * g.rh);
    }
    const slot = pat.steps[c];
    if (live && slot > 0) {
      const r = rows - Math.min(slot, rows);
      ctx.fillStyle = pat.dir === CUSTOM ? color.glow : color.ink;
      ctx.fillRect(Math.round(x) + 1, Math.round(g.y0 + r * g.rh) + 1, Math.max(1, g.cw - 2), Math.max(1, g.rh - 2));
    }
    // The length strip: lit up to the last step, so dragging it reads as dragging the end.
    ctx.fillStyle = live ? color.ink : "rgba(184,240,160,0.12)";
    ctx.fillRect(Math.round(x) + 1, Math.round(g.stripY), Math.max(1, g.cw - 2), STRIP - 2);
    // Its velocity, then its gate — bright when drawn, dim on a preset, faint past the end.
    const lit = !live ? "rgba(184,240,160,0.12)" : pat.dir === CUSTOM ? color.glow : color.dim;
    drawBar(ctx, x, g.cw, g.velY, pat.vel[c], lit, color);
    drawBar(ctx, x, g.cw, g.gateY, gateFill(pat.gate[c]), lit, color);
  }
}

// The cell under the pointer, the strip, or a bar with the value at that height; null outside.
function hit(lcd, ev) {
  const rows = rowsOf(lcd.params);
  const g = layout(lcd.width, lcd.height, rows);
  const col = Math.floor((ev.x - g.x0) / g.cw);
  if (col < 0 || col >= MAX) return null;
  if (ev.y >= g.gateY - GAP / 2) return { col, bar: "gate", value: barValue(g.gateY, ev.y) };
  if (ev.y >= g.velY - GAP / 2) return { col, bar: "velocity", value: barValue(g.velY, ev.y) };
  if (ev.y >= g.stripY - 1) return { col, strip: true };
  const r = Math.floor((ev.y - g.y0) / g.rh);
  if (r < 0 || r >= rows) return null;
  return { col, slot: rows - r };
}

// The first edit of a gesture on a preset makes it Custom, holding what the screen was showing.
function begin(lcd) {
  const pat = patternOf(lcd.params);
  if (pat.dir !== CUSTOM) {
    lcd.set("Direction", CUSTOM);
    lcd.set("Steps", pat.length);
    for (let i = 0; i < MAX; i++) {
      lcd.set(`Step ${i + 1}`, pat.steps[i]);
      lcd.set(`Velocity ${i + 1}`, pat.vel[i]);
      lcd.set(`Gate ${i + 1}`, pat.gate[i]);
    }
  }
  lcd.state.edit = {
    steps: pat.steps.slice(),
    vel: pat.vel.slice(),
    gate: pat.gate.slice(),
    length: pat.length,
    mode: null,
    col: null,
  };
}

// A bar dragged: the step under the pointer takes the height, so a sweep across draws a curve.
function setLevel(lcd, at) {
  const e = lcd.state.edit;
  e.col = at.col;
  if (e.mode === "velocity") {
    const v = Math.round(at.value * 100) / 100;
    if (e.vel[at.col] !== v) {
      e.vel[at.col] = v;
      lcd.set(`Velocity ${at.col + 1}`, v);
    }
  } else {
    const v = Math.round((GATE_MIN + at.value * (GATE_MAX - GATE_MIN)) * 100) / 100;
    if (e.gate[at.col] !== v) {
      e.gate[at.col] = v;
      lcd.set(`Gate ${at.col + 1}`, v);
    }
  }
}

function setStep(lcd, col, value) {
  const e = lcd.state.edit;
  if (e.steps[col] !== value) {
    e.steps[col] = value;
    lcd.set(`Step ${col + 1}`, value);
  }
  // Drawing past the end lengthens the pattern to reach it.
  if (value > 0 && col + 1 > e.length) setLength(lcd, col + 1);
}

function setLength(lcd, length) {
  const e = lcd.state.edit;
  if (e.length === length) return;
  e.length = length;
  lcd.set("Steps", length);
}

function pointer(lcd, ev) {
  if (ev.type === "up") {
    lcd.state.edit = null;
    return true;
  }
  const at = hit(lcd, ev);
  if (ev.type === "down") {
    if (!at) return true;
    begin(lcd);
    const e = lcd.state.edit;
    // A press on a lit cell erases along the drag; anywhere else it paints that row. A bar sets levels.
    e.mode = at.bar ?? (at.strip ? "length" : e.steps[at.col] === at.slot ? "erase" : "paint");
  }
  const e = lcd.state.edit;
  if (!e || !at) return true;
  if (e.mode === "velocity" || e.mode === "gate") {
    // Off the bars, the pointer still steers the column; its height clamps to the bar's ends.
    const g = layout(lcd.width, lcd.height, rowsOf(lcd.params));
    const top = e.mode === "velocity" ? g.velY : g.gateY;
    setLevel(lcd, { col: at.col, value: barValue(top, ev.y) });
  } else if (e.mode === "length") setLength(lcd, at.col + 1);
  else if (!at.strip && !at.bar) setStep(lcd, at.col, e.mode === "erase" ? 0 : at.slot);
  return true;
}

export default {
  pattern: { draw, pointer },
};

// 4osc screens: the four oscillator waves, the filter response, the envelopes, the LFOs and the FX tails.
const BLUE = "#3d7dff", GREEN = "#3ec96b", WHITE = "#ffffff", ORANGE = "#ff6a1a", RED = "#ff3b30", GREY = "#6b6b6b";
const FONT = "8px ui-monospace, monospace";
const SHAPES = ["OFF", "SINE", "TRI", "SAW+", "SAW-", "SQR", "RND"];

function clear(lcd) {
  lcd.ctx.fillStyle = "#000";
  lcd.ctx.fillRect(0, 0, lcd.width, lcd.height);
}

function text(ctx, s, x, y, c, align) {
  ctx.fillStyle = c;
  ctx.font = FONT;
  ctx.textAlign = align || "left";
  ctx.fillText(s, x, y);
}

// One sample of a 4OSC wave shape at phase ph (0..1), pulse width pw.
function wave(shape, ph, pw) {
  const p = ph - Math.floor(ph);
  switch (Math.round(shape)) {
    case 1: return Math.sin(2 * Math.PI * p);
    case 2: return p < 0.5 ? 4 * p - 1 : 3 - 4 * p;
    case 3: return 2 * p - 1;
    case 4: return 1 - 2 * p;
    case 5: return p < pw ? 1 : -1;
    case 6: { const k = Math.floor(ph * 6); const h = Math.sin(k * 12.9898 + 78.233) * 43758.5453; return 2 * (h - Math.floor(h)) - 1; }
    default: return 0;
  }
}

function plotWave(ctx, shape, x, y, w, h, amp, cycles, pw, offset, col) {
  ctx.strokeStyle = col;
  ctx.lineWidth = 1;
  ctx.beginPath();
  const n = Math.max(2, Math.floor(w));
  for (let i = 0; i <= n; i++) {
    const v = wave(shape, (i / n) * cycles + offset, pw);
    const px = x + (i / n) * w, py = y + h / 2 - v * amp * (h / 2);
    if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
  }
  ctx.stroke();
}

// Seconds onto a compressed axis so 1 ms and 60 s both read.
const tx = (t) => Math.log10(1 + Math.max(0, t) * 20);

function adsr(ctx, a, d, s, r, x, y, w, h, scale, col) {
  const hold = 0.6;
  const xa = x + (tx(a) / scale) * w, xd = xa + (tx(d) / scale) * w;
  const xs = xd + (hold / scale) * w, xr = xs + (tx(r) / scale) * w;
  const ys = y + h - s * h;
  ctx.strokeStyle = col;
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(x, y + h);
  ctx.lineTo(xa, y);
  ctx.lineTo(xd, ys);
  ctx.lineTo(xs, ys);
  ctx.lineTo(xr, y + h);
  ctx.stroke();
  ctx.fillStyle = col;
  ctx.beginPath();
  ctx.arc(xa, y, 2, 0, 2 * Math.PI);
  ctx.fill();
}

const envScale = (...sets) => Math.max(1, ...sets.map(([a, d, r]) => tx(a) + tx(d) + 0.6 + tx(r))) * 1.05;

function peak(arr) {
  if (!arr || !arr.length) return 0;
  let m = 0;
  for (let i = Math.max(0, arr.length - 16); i < arr.length; i++) m = Math.max(m, arr[i] || 0);
  return m;
}

export default {
  osc_screen(lcd) {
    clear(lcd);
    const { ctx, width: W, height: H, params: p } = lcd;
    const lane = H / 4;
    for (let i = 1; i <= 4; i++) {
      const y = (i - 1) * lane;
      const shape = p[`Wave Shape ${i}`] ?? (i === 1 ? 3 : 0);
      const lvl = Math.pow(10, (p[`Level ${i}`] ?? 0) / 20);
      const pw = p[`Pulse Width ${i}`] ?? 0.5;
      const tune = Math.round(p[`Tune ${i}`] ?? 0);
      const voices = Math.max(1, Math.round(p[`Voices ${i}`] ?? 1));
      const det = p[`Detune ${i}`] ?? 0;
      const on = Math.round(shape) > 0;
      if (i > 1) { ctx.fillStyle = "#1a1a1a"; ctx.fillRect(0, y, W, 1); }
      const top = y + 11, h = lane - 15;
      const cycles = Math.min(6, 2 * Math.pow(2, tune / 24));
      if (!on) {
        ctx.strokeStyle = GREY;
        ctx.beginPath(); ctx.moveTo(4, top + h / 2); ctx.lineTo(W - 4, top + h / 2); ctx.stroke();
      } else {
        for (let v = 1; v < Math.min(voices, 4); v++)
          plotWave(ctx, shape, 4, top, W - 8, h, lvl * 0.9, cycles * (1 + det * 0.15 * v), pw, v * det * 0.4, GREY);
        plotWave(ctx, shape, 4, top, W - 8, h, lvl * 0.9, cycles, pw, 0, BLUE);
      }
      text(ctx, `${i} ${SHAPES[Math.round(shape)] || "?"}`, 4, y + 9, on ? WHITE : GREY);
      const t = `${tune > 0 ? "+" : ""}${tune}${voices > 1 ? ` x${voices}` : ""}`;
      text(ctx, t, W - 4, y + 9, on ? WHITE : GREY, "right");
    }
  },

  filter_screen(lcd) {
    clear(lcd);
    const { ctx, width: W, height: H, params: p } = lcd;
    const type = Math.round(p["Filter Type"] ?? 1);
    const note = p["Filter Freq"] ?? 69;
    const fc = 440 * Math.pow(2, (note - 69) / 12);
    const q = 0.707 + ((p["Filter Resonance"] ?? 0.5) / 100) * 12;
    const steep = (p["Filter Slope"] ?? 12) >= 24 ? 2 : 1;
    const amt = p["Filter Amount"] ?? 0;
    const fx = (f) => (Math.log10(f / 20) / 3) * W;
    const dbY = (db) => 4 + ((18 - Math.max(-42, Math.min(18, db))) / 60) * (H - 8);
    const mag = (f, c) => {
      const w = f / c, re = 1 - w * w, im = w / q, den = Math.sqrt(re * re + im * im) || 1e-9;
      let m = 1;
      if (type === 1) m = 1 / den;
      else if (type === 2) m = (w * w) / den;
      else if (type === 3) m = (w / q) / den;
      else if (type === 4) m = Math.abs(1 - w * w) / den;
      return 20 * Math.log10(Math.pow(Math.max(m, 1e-6), steep));
    };
    ctx.strokeStyle = "#1a1a1a";
    ctx.beginPath(); ctx.moveTo(0, dbY(0)); ctx.lineTo(W, dbY(0)); ctx.stroke();
    const curve = (c, col) => {
      ctx.strokeStyle = col;
      ctx.beginPath();
      for (let x = 0; x <= W; x++) {
        const f = 20 * Math.pow(1000, x / W), y = dbY(type === 0 ? 0 : mag(f, c));
        if (x === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      }
      ctx.stroke();
    };
    if (type !== 0 && Math.abs(amt) > 0.01) curve(Math.min(20000, Math.max(20, fc * Math.pow(2, amt * 5))), GREY);
    curve(fc, type === 0 ? GREY : ORANGE);
    if (type !== 0) {
      ctx.fillStyle = ORANGE;
      ctx.beginPath(); ctx.arc(fx(Math.min(20000, Math.max(20, fc))), dbY(mag(fc, fc)), 2.5, 0, 2 * Math.PI); ctx.fill();
    }
    const hz = fc >= 1000 ? `${(fc / 1000).toFixed(1)}K` : `${Math.round(fc)}`;
    text(ctx, ["OFF", "LP", "HP", "BP", "NOTCH"][type] || "", 4, 10, WHITE);
    text(ctx, type === 0 ? "" : hz, W - 4, 10, ORANGE, "right");
  },

  env_screen(lcd) {
    clear(lcd);
    const { ctx, width: W, height: H, params: p, output } = lcd;
    const amp = [p["Amp Attack"] ?? 0.1, p["Amp Decay"] ?? 0.1, p["Amp Release"] ?? 0.1];
    const flt = [p["Filter Attack"] ?? 0.1, p["Filter Decay"] ?? 0.1, p["Filter Release"] ?? 0.1];
    const sc = envScale(amp, flt);
    const amt = p["Filter Amount"] ?? 0;
    const x = 6, y = 14, w = W - 12, h = H - 22;
    if (Math.abs(amt) > 0.01) adsr(ctx, flt[0], flt[1], (p["Filter Sustain"] ?? 80) / 100, flt[2], x, y + h * (1 - Math.abs(amt)), w, h * Math.abs(amt), sc, ORANGE);
    else adsr(ctx, flt[0], flt[1], (p["Filter Sustain"] ?? 80) / 100, flt[2], x, y, w, h, sc, GREY);
    adsr(ctx, amp[0], amp[1], (p["Amp Sustain"] ?? 80) / 100, amp[2], x, y, w, h, sc, WHITE);
    const lv = peak(output);
    if (lv > 0.001) { ctx.fillStyle = GREEN; ctx.fillRect(W - 4, y + h - lv * h, 2, lv * h); }
    text(ctx, "AMP", 4, 9, WHITE);
    text(ctx, "FLT", 28, 9, Math.abs(amt) > 0.01 ? ORANGE : GREY);
  },

  mod_screen(lcd) {
    clear(lcd);
    const { ctx, width: W, height: H, params: p, now } = lcd;
    const half = H / 2;
    const lfos = [[1, BLUE], [2, GREEN]];
    for (const [i, col] of lfos) {
      const y = 12 + (i - 1) * (half / 2 - 4), h = half / 2 - 14;
      const shape = p[`LFO Shape ${i}`] ?? 0;
      const rate = p[`Rate ${i}`] ?? 1;
      const depth = p[`Depth ${i}`] ?? 1;
      const cycles = Math.max(0.5, Math.min(8, 1 + Math.log2(1 + rate)));
      const on = Math.round(shape) > 0;
      const ph = on ? ((now || 0) / 1000) * Math.min(rate, 4) * 0.25 : 0;
      if (on) plotWave(ctx, shape, 30, y, W - 34, h, Math.max(0.05, depth), cycles, 0.5, -ph, col);
      else { ctx.strokeStyle = GREY; ctx.beginPath(); ctx.moveTo(30, y + h / 2); ctx.lineTo(W - 4, y + h / 2); ctx.stroke(); }
      text(ctx, `LFO${i}`, 4, y + h / 2 + 3, on ? col : GREY);
    }
    ctx.fillStyle = "#1a1a1a";
    ctx.fillRect(0, half, W, 1);
    const m1 = [p["Mod Attack 1"] ?? 0.1, p["Mod Decay 1"] ?? 0.1, p["Mod Release 1"] ?? 0.1];
    const m2 = [p["Mod Attack 2"] ?? 0.1, p["Mod Decay 2"] ?? 0.1, p["Mod Release 2"] ?? 0.1];
    const sc = envScale(m1, m2);
    const y = half + 16, h = half - 24;
    adsr(ctx, m2[0], m2[1], (p["Mod Sustain 2"] ?? 80) / 100, m2[2], 6, y, W - 12, h, sc, GREEN);
    adsr(ctx, m1[0], m1[1], (p["Mod Sustain 1"] ?? 80) / 100, m1[2], 6, y, W - 12, h, sc, BLUE);
    text(ctx, "MOD1", 4, half + 10, BLUE);
    text(ctx, "MOD2", 34, half + 10, GREEN);
  },

  fx_screen(lcd) {
    clear(lcd);
    const { ctx, width: W, height: H, params: p } = lcd;
    const half = H / 2;
    const dOn = (p["Delay On"] ?? 0) >= 0.5;
    const time = Math.max(0.05, p["Delay"] ?? 1);
    const fb = Math.pow(10, (p["Feedback"] ?? -10) / 20);
    const dMix = p["Mix #2"] ?? 0;
    const base = half - 6, top = 14;
    ctx.fillStyle = WHITE;
    ctx.fillRect(4, top, 3, base - top);
    const step = Math.max(4, ((W - 12) / 4) * (time / 1));
    let a = Math.max(0.08, dMix);
    for (let x = 4 + step, k = 0; x < W - 4 && k < 32; x += step, k++) {
      const h = (base - top) * a;
      ctx.fillStyle = dOn ? GREEN : GREY;
      ctx.fillRect(x, base - h, 3, h);
      a *= fb;
      if (a < 0.01) break;
    }
    text(ctx, "DELAY", 4, 9, dOn ? GREEN : GREY);
    ctx.fillStyle = "#1a1a1a";
    ctx.fillRect(0, half, W, 1);
    const rOn = (p["Reverb On"] ?? 0) >= 0.5;
    const size = p["Size"] ?? 0;
    const damp = p["Damping"] ?? 0;
    const rMix = Math.max(0.08, p["Mix #3"] ?? 0);
    const rb = H - 4, rt = half + 14, len = (W - 8) * (0.15 + 0.85 * size);
    ctx.fillStyle = rOn ? WHITE : GREY;
    ctx.beginPath();
    ctx.moveTo(4, rb);
    for (let i = 0; i <= 40; i++) {
      const t = i / 40, env = Math.exp(-t * (3 + damp * 3)) * (1 - t);
      ctx.lineTo(4 + t * len, rb - env * (rb - rt) * rMix);
    }
    ctx.lineTo(4 + len, rb);
    ctx.closePath();
    ctx.fill();
    text(ctx, "REVERB", 4, half + 10, rOn ? WHITE : GREY);
    const dist = (p["Distortion On"] ?? 0) >= 0.5, chor = (p["Chorus On"] ?? 0) >= 0.5;
    text(ctx, "DIST", W - 4, 9, dist ? RED : GREY, "right");
    text(ctx, "CHO", W - 34, 9, chor ? BLUE : GREY, "right");
  },
};
